import os
import launch
from launch.actions import IncludeLaunchDescription
from launch.launch_description_sources import AnyLaunchDescriptionSource
from ament_index_python.packages import get_package_share_directory


def generate_launch_description():
    d = os.path.join(get_package_share_directory('agnocast_sample_application'), 'launch')
    names = os.environ.get('AGNOCAST_SAMPLES', 'talker listener no_rclcpp_talker no_rclcpp_listener').split()
    return launch.LaunchDescription([
        IncludeLaunchDescription(AnyLaunchDescriptionSource(os.path.join(d, n + '.launch.xml'))) for n in names])
